data.query:
query DataModelDetails($where: DataModelWhereInput) {
  dataModel(where: $where, first: 1) {
    edges {
      node {
        id
        name
        description
        dataModelKindId
        dataModelTypeId
        estimatedRecordCount
        estimatedDataBytes
        module {
          id
          name
          description
          system
        }
        elements(first: 500) {
          edges {
            node {
              id
              name
              type
              description
              unique
              labelField
              relation
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $modelData := dataModel.edges[0].node;
  $modelData ? {
    "model": {
      "id": $modelData.id,
      "name": $modelData.name,
      "description": $modelData.description,
      "module": $modelData.module,
      "dataModelKindId": $modelData.dataModelKindId,
      "dataModelTypeId": $modelData.dataModelTypeId,
      "estimatedRecordCount": $modelData.estimatedRecordCount,
      "estimatedDataBytes": $modelData.estimatedDataBytes
    },
    "elements": $map($modelData.elements.edges.node, function($el) {
      {
        "id": $el.id,
        "name": $el.name,
        "type": $el.type,
        "description": $el.description,
        "unique": $el.unique,
        "labelField": $el.labelField,
        "relation": $el.relation,
        "complexType": $not($el.type in ["String", "String!", "Int", "Int!", "Float", "Float!", "Boolean", "Boolean!", "ID", "ID!", "DateTime", "DateTime!", "Date", "Date!", "JSON", "JSON!", "BigInt", "BigInt!", "Decimal", "Decimal!"]) and $not($contains($el.type, "[")) and $el.relation = false,
        "subfields": $lookup({"Measure": {"value": {"type": "Float", "nullable": false}, "unit": {"type": "Unit", "relation": true, "subfields": {"id": {"type": "ID"}, "code": {"type": "String"}}}}, "Measure!": {"value": {"type": "Float", "nullable": false}, "unit": {"type": "Unit", "relation": true, "subfields": {"id": {"type": "ID"}, "code": {"type": "String"}}}}, "Address": {"line1": {"type": "String", "nullable": true}, "line2": {"type": "String", "nullable": true}, "city": {"type": "String", "nullable": true}, "state": {"type": "String", "nullable": true}, "postalCode": {"type": "String", "nullable": true}, "country": {"type": "String", "nullable": true}}, "Address!": {"line1": {"type": "String", "nullable": true}, "line2": {"type": "String", "nullable": true}, "city": {"type": "String", "nullable": true}, "state": {"type": "String", "nullable": true}, "postalCode": {"type": "String", "nullable": true}, "country": {"type": "String", "nullable": true}}, "Money": {"amount": {"type": "Decimal", "nullable": false}, "currency": {"type": "String", "nullable": false}}, "Money!": {"amount": {"type": "Decimal", "nullable": false}, "currency": {"type": "String", "nullable": false}}}, $el.type)
      }
    }),
    "summary": {
      "totalElements": $count($modelData.elements.edges),
      "relationFields": $count($modelData.elements.edges.node[relation = true]),
      "uniqueFields": $count($modelData.elements.edges.node[unique = true])
    }
  } : {
    "error": "Model not found"
  }
)

/*
 * Format as Markdown — DataModel Details
 * Input: JSON from Format Response { model, elements, summary }
 * Output: Markdown string via $jsonToMarkdown()
 */

var d = $;
if (!d.model) {
  return $jsonToMarkdown([
    { "h2": "DataModel Details" },
    { "p": d.error || "Model not found." }
  ]);
}

var md = [];

/* Header */
md.push({ "h2": "Data Model: " + d.model.name });
if (d.model.description) md.push({ "p": d.model.description });

var meta = [];
if (d.model.module) meta.push("**Module:** " + d.model.module.name);
meta.push("**Kind:** " + (d.model.dataModelKindId || "?"));
meta.push("**Type:** " + (d.model.dataModelTypeId || "?"));
if (d.model.estimatedRecordCount != null) meta.push("**Records:** ~" + d.model.estimatedRecordCount);
md.push({ "p": meta.join(" | ") });

/* Elements table */
var elements = d.elements || [];
if (elements.length > 0) {
  var rows = [];
  var relationList = [];

  for (var i = 0; i < elements.length; i++) {
    var el = elements[i];
    var flags = [];
    if (el.unique) flags.push("UQ");
    if (el.labelField) flags.push("LBL");

