    if (el.relation) {
      relationList.push(el.name + " -> " + el.type);
      typeDisplay = "-> " + el.type;
    } else if (el.complexType && el.subfields) {
      var subs = Object.keys(el.subfields).join(", ");
      typeDisplay = el.type + " {" + subs + "}";
    }

    rows.push([
      el.name,
      typeDisplay,
      flags.join(", "),
      (el.description || "").replace(/\|/g, "/").substring(0, 60)
    ]);
  }

  md.push({ "h3": "Fields (" + elements.length + ")" });
  md.push({ "table": {
    "headers": ["Field", "Type", "Flags", "Description"],
    "rows": rows
  }});

  if (relationList.length > 0) {
    md.push({ "h3": "Relations (" + relationList.length + ")" });
    md.push({ "ul": relationList });
  }
}

/* Summary */
md.push({ "p": "**Summary:** " + d.summary.totalElements + " fields, "
  + d.summary.relationFields + " relations, "
  + d.summary.uniqueFields + " unique" });

return $jsonToMarkdown(md);

