  "String": true, "Int": true, "Float": true, "Boolean": true,
  "ID": true, "DateTime": true, "Date": true, "JSON": true,
  "BigInt": true, "Decimal": true
};

// Build field selection per model
const buildFields = (fields) => {
  const parts = ["id"];
  for (const f of (fields || [])) {
    if (!f || !f.name) continue;
    if (f.name === "id") continue;
    // skip arrays and unknown complex types — extend if you have type metadata
    if (f.type && SCALAR_TYPES[f.type]) {
      parts.push(f.name);
    } else if (f.type === "relation" || (f.type && f.type.endsWith("Relation"))) {
      parts.push(f.name + " { id }");
    }
    // arrays / embeddables: skip for now, log if needed
  }
  // dedupe
  const seen = {};
  const out = [];
  for (const p of parts) {
    if (!seen[p]) { seen[p] = true; out.push(p); }
  }
  return out.join(" ");
};

// Build aliased query blocks
const blocks = [];
const modelMap = {}; // alias -> model meta
for (const m of models) {
  if (!m.name) continue;
  const lower = m.name.charAt(0).toLowerCase() + m.name.slice(1);
  const alias = lower + "_seed";
  const fieldsStr = buildFields(m.fields);
  blocks.push(
    `${alias}: ${lower}(first: 1000) { ` +
    `total edges { node { ${fieldsStr} } } ` +
    `pageInfo { hasNextPage endCursor } }`
  );
  modelMap[alias] = { name: m.name, source: m.source, description: m.description };
}

const statement = `query AllSeedData { ${blocks.join(" ")} }`;

// Execute — $graphql is the Script-node entry point for runtime queries
let result;
try {
  result = await $graphql("application", statement, {});
} catch (e) {
  return {
    error: e.message,
    statement: statement,
    models: models.map(m => m.name)
  };
}

// Reshape into seedData[]
const seedData = [];
let totalRecords = 0;
for (const alias of Object.keys(modelMap)) {
  const bucket = result[alias] || {};
  const meta = modelMap[alias];
  const count = (bucket.edges || []).length;
  totalRecords += (bucket.total || 0);
  seedData.push({
    modelName: meta.name,
    source: meta.source,
    description: meta.description,
    data: (bucket.edges || []).map(e => e.node),
    total: bucket.total || 0,
    returnedCount: count,
    hasNextPage: bucket.pageInfo && bucket.pageInfo.hasNextPage,
    endCursor: bucket.pageInfo && bucket.pageInfo.endCursor
  });
}

return {
  seedData: seedData,
  summary: {
    modelCount: models.length,
    totalRecords: totalRecords,
    bySource: {
      system: seedData.filter(s => s.source === "system").length,
      custom: seedData.filter(s => s.source === "custom").length,
      setup: seedData.filter(s => s.source === "setup").length
    }
  },
  _models: models,
  _generatedQuery: statement
};

